                  <p className="text-sm font-medium">特征：</p>
                  <ul className="list-disc list-inside space-y-1 text-sm text-muted-foreground">
                    {review.report.errorAnalysis.psychologicalProfile.characteristics.map((char, i) => (
                      <li key={i}>{char}</li>
